nav='''<div class="topbar"><div class="container"><span>Institutional RWA infrastructure for industrial metals</span><span>Prelaunch • Switzerland (pre-incorporation)</span></div></div><nav class="nav"><div class="container navin"><a class="brand" href="index.html"><span class="mark">R</span><span>ReserveChain</span></a><div class="links"><a href="copper.html">Copper</a><a href="nickel.html">Nickel</a><a href="registry.html">Registry</a><a href="passport.html">Passports</a><a href="verification.html">Verification</a><a href="tokenization.html">Tokenization</a><a href="documents.html">Documents</a></div><a class="btn primary" href="waitlist.html">Join Waitlist</a></div></nav>'''
footer='''<footer class="footer"><div class="container footergrid"><div><div class="brand"><span class="mark">R</span><span>ReserveChain</span></div><p class="small">Institutional-grade infrastructure for proposed tokenization of verified industrial-metal programs.</p></div><div><strong>Explore</strong><p><a href="roadmap.html">Roadmap</a><br><a href="architecture.html">Architecture</a><br><a href="admin.html">CMS Demo</a><br><a href="schedule.html">Development Plan</a></p></div><div><strong>Legal</strong><p><a href="faq.html">FAQ</a><br><a href="waitlist.html">Waitlist</a><br><a href="documents.html">Disclosures</a></p></div></div><div class="container legal" style="margin-top:28px">ReserveChain is currently in development. No tokens are being offered or sold through this website. Registration of interest does not constitute an investment, token purchase, asset reservation, price reservation, token allocation or entitlement to participate in any future offering. Any future availability will be subject to the final Swiss corporate and legal structure, definitive offering documentation, asset verification, custody arrangements, jurisdictional eligibility, KYC/KYB, sanctions screening and final approval.<br><br>© <span id="year"></span> ReserveChain concept prototype.</div></footer><script src="assets/app.js"></script>'''
def page(title, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | ReserveChain</title><meta name="description" content="ReserveChain institutional industrial-metal tokenization platform prototype"><link rel="stylesheet" href="assets/style.css"></head><body>{nav}{body}{footer}</body></html>'''

disclosure='''<div class="notice"><strong>Prelaunch disclosure:</strong> ReserveChain is currently in development. No tokens are being offered or sold through this website. Registration of interest does not constitute an investment, token purchase, asset reservation, price reservation, token allocation or entitlement to participate in any future offering. Any future availability will be subject to the final Swiss corporate and legal structure, definitive offering documentation, asset verification, custody arrangements, jurisdictional eligibility, KYC/KYB, sanctions screening and final approval.</div>'''

pages={}
pages['index.html']=page('Institutional RWA Infrastructure',f'''<header class="hero"><div class="container"><div class="eyebrow">Industrial metals • Digital infrastructure</div><h1>Physical reserves.<br>Digital transparency.</h1><p>ReserveChain is building institutional infrastructure for the proposed tokenization, registry, verification and lifecycle management of high-purity industrial metals—starting with Copper Powder and Nickel Wire.</p><div class="actions"><a class="btn primary" href="registry.html">Explore Asset Registry</a><a class="btn ghost" href="passport.html">View Sample Passport</a></div>{disclosure}</div></header><section class="section alt"><div class="container"><div class="eyebrow">Initial programs</div><h2>Two industrial-metal programs</h2><p class="lead">Illustrative prototype records only. Final laboratory, ownership, custody, insurance, valuation and reserve information will be published only after approval.</p><div class="grid g2" style="margin-top:26px"><a class="card metal" href="copper.html"><span class="tag green">Proposed Program 01</span><h3>Ultra-High-Purity Copper Powder</h3><p>Batch-level specifications, certificates, packaging, reserve status and future token-program linkage.</p></a><a class="card metal" href="nickel.html"><span class="tag green">Proposed Program 02</span><h3>High-Purity Nickel Wire</h3><p>Coil-level technical records, documents, custody fields and future reserve/redemption status.</p></a></div></div></section><section class="section"><div class="container"><div class="grid g4"><div class="card"><span class="tag">Registry</span><h3>Structured asset records</h3><p>Programs, lots, batches, coils, documents and status controls.</p></div><div class="card"><span class="tag">Passports</span><h3>Digital Asset Passports</h3><p>Human-readable and machine-ready records for each verified unit.</p></div><div class="card"><span class="tag">Compliance</span><h3>Configurable controls</h3><p>Jurisdiction, KYC/KYB, sanctions, eligibility and transfer rules.</p></div><div class="card"><span class="tag">Future modules</span><h3>Reserves & redemption</h3><p>Designed now, inactive until authorized and verified.</p></div></div></div></section>''')

metal_template=lambda name,kind,unit: page(name,f'''<header class="hero"><div class="container"><div class="eyebrow">Proposed metal program</div><h1>{name}</h1><p>Institutional asset-program page for technical specifications, {kind} records, documents, reserve status and future token-program linkage.</p>{disclosure}</div></header><section class="section alt"><div class="container grid g2"><div class="card"><span class="tag warn">Illustrative template</span><h3>Technical specification fields</h3><div class="spec"><span>Purity</span><span>Pending verified laboratory data</span></div><div class="spec"><span>{unit} ID</span><span>Illustrative only</span></div><div class="spec"><span>Net weight</span><span>Pending verification</span></div><div class="spec"><span>Packaging</span><span>Pending approved record</span></div><div class="spec"><span>Certificate of Analysis</span><span>Not yet supplied</span></div></div><div class="card"><h3>Lifecycle controls</h3><div class="spec"><span>Ownership record</span><span>Pending</span></div><div class="spec"><span>Custody</span><span>Not confirmed</span></div><div class="spec"><span>Insurance</span><span>Not confirmed</span></div><div class="spec"><span>Valuation</span><span>Not supplied</span></div><div class="spec"><span>Reserve status</span><span>Inactive / prelaunch</span></div></div></div></section><section class="section"><div class="container"><h2>What this module will manage</h2><div class="grid g3"><div class="card"><h3>Documents</h3><p>Laboratory reports, Certificates of Analysis, ownership and approved evidence.</p></div><div class="card"><h3>Unit records</h3><p>{kind.capitalize()} IDs, weights, packaging, verification states and history.</p></div><div class="card"><h3>Future token linkage</h3><p>Configurable mapping to approved token programs without hard-coded economics.</p></div></div></div></section>''')
pages['copper.html']=metal_template('Ultra-High-Purity Copper Powder','batch/container','Batch / Container')
pages['nickel.html']=metal_template('High-Purity Nickel Wire','coil','Coil')

pages['registry.html']=page('Asset Registry',f'''<header class="hero"><div class="container"><div class="eyebrow">Industrial-metal registry</div><h1>Asset Registry</h1><p>A scalable registry structure for programs, lots, batches, containers, coils, laboratories, documents, valuations, custody, insurance, reserve reports, token programs and redemption status.</p>{disclosure}</div></header><section class="section alt"><div class="container"><div class="tablewrap"><table class="table"><thead><tr><th>Record ID</th><th>Program</th><th>Unit Type</th><th>Verification</th><th>Reserve Module</th><th>Public State</th></tr></thead><tbody><tr><td>RC-CU-DEMO-001</td><td>Copper Powder</td><td>Batch</td><td><span class="status pending">Illustrative</span></td><td>Inactive</td><td>Template</td></tr><tr><td>RC-NI-DEMO-001</td><td>Nickel Wire</td><td>Coil</td><td><span class="status pending">Illustrative</span></td><td>Inactive</td><td>Template</td></tr></tbody></table></div><p class="small" style="margin-top:14px">Demo rows contain no real quantities, valuations, custodians, insurers, token prices or contract addresses.</p></div></section>''')

pages['passport.html']=page('Digital Asset Passport',f'''<header class="hero"><div class="container"><div class="eyebrow">Sample record</div><h1>Digital Asset Passport</h1><p>A structured, traceable view of an industrial-metal unit and its approved evidence.</p>{disclosure}</div></header><section class="section alt"><div class="container"><div class="passport"><div class="passporthead"><div><span class="tag warn">Illustrative template</span><h2 style="margin-bottom:6px">Copper Powder • Sample Batch</h2><div class="mono">Passport ID: RC-DAP-DEMO-CU-001</div></div><div><span class="status pending">Under Review</span></div></div><div class="passportbody grid g2"><div><h3>Asset identity</h3><div class="spec"><span>Program</span><span>Copper Powder</span></div><div class="spec"><span>Batch / Container ID</span><span>Illustrative only</span></div><div class="spec"><span>Weight</span><span>Pending verified record</span></div><div class="spec"><span>Purity</span><span>Pending laboratory data</span></div></div><div><h3>Evidence & controls</h3><div class="spec"><span>Certificate of Analysis</span><span>Not supplied</span></div><div class="spec"><span>Ownership</span><span>Pending</span></div><div class="spec"><span>Custody</span><span>Not confirmed</span></div><div class="spec"><span>Token linkage</span><span>Inactive</span></div></div></div></div></div></section>''')

pages['verification.html']=page('Verification & Proof of Reserves',f'''<header class="hero"><div class="container"><div class="eyebrow">Verification framework</div><h1>Evidence before issuance.</h1><p>ReserveChain is designed to reconcile approved inventory evidence, token supply and reserve calculations while preserving a historical audit record.</p>{disclosure}</div></header><section class="section alt"><div class="container"><h2>Future Proof-of-Reserves workflow</h2><div class="grid g3" style="margin-top:24px"><div class="card"><h3>1. Inventory evidence</h3><p>Approved unit records and documents enter the registry.</p></div><div class="card"><h3>2. Reconciliation</h3><p>Reserve calculations compare approved asset data with authorized token supply.</p></div><div class="card"><h3>3. Attestation history</h3><p>Discrepancies, attestations and historical reports remain traceable.</p></div></div><div class="notice">Proof-of-Reserves is a planned module only and remains inactive until verified information and final approvals are available.</div></div></section>''')

pages['tokenization.html']=page('Tokenization',f'''<header class="hero"><div class="container"><div class="eyebrow">Proposed ERC-20 architecture</div><h1>Configurable by design.</h1><p>Future token programs are intended to support configurable name, symbol, supply, minting, burning, role permissions, pause controls, multisignature-compatible administration, treasury controls and redemption burn workflows.</p>{disclosure}</div></header><section class="section alt"><div class="container grid g2"><div class="card"><h3>Smart-contract controls</h3><div class="spec"><span>Mint / burn</span><span>Role-controlled</span></div><div class="spec"><span>Pause</span><span>Supported</span></div><div class="spec"><span>Multisig admin</span><span>Planned</span></div><div class="spec"><span>Mainnet</span><span>Not authorized</span></div></div><div class="card"><h3>Tokenomics configuration</h3><p>Supply, allocations, treasury, fees, reserve ratios, redemption and reporting remain configurable and must not be hard-coded before written approval.</p></div></div></section>''')

pages['enterprise.html']=page('Enterprise Services',f'''<header class="hero"><div class="container"><div class="eyebrow">Enterprise infrastructure</div><h1>Designed for controlled institutional workflows.</h1><p>Future enterprise services can support approved counterparties, asset onboarding, structured document exchange, compliance workflows and operational reporting.</p>{disclosure}</div></header><section class="section alt"><div class="container grid g3"><div class="card"><h3>Asset onboarding</h3><p>Structured program and unit records with approval states.</p></div><div class="card"><h3>Compliance workflows</h3><p>Configurable eligibility, KYC/KYB, sanctions and jurisdiction controls.</p></div><div class="card"><h3>Operational reporting</h3><p>Documents, reserve data and lifecycle reporting from one system.</p></div></div></section>''')

pages['documents.html']=page('Documents & Whitepaper',f'''<header class="hero"><div class="container"><div class="eyebrow">Institutional documentation</div><h1>Documents & Whitepaper</h1><p>The production platform will provide approved legal notices, technical documentation, whitepaper materials and asset evidence with publication controls.</p>{disclosure}</div></header><section class="section alt"><div class="container"><div class="grid g3"><div class="card"><span class="tag warn">Pending</span><h3>Institutional Whitepaper</h3><p>Project model, metals, legal/custody/reserve frameworks, architecture, governance, security, compliance, redemption, roadmap and risks.</p></div><div class="card"><span class="tag warn">Pending</span><h3>Offering / legal materials</h3><p>To be supplied by the owner and appointed advisers.</p></div><div class="card"><span class="tag warn">Pending</span><h3>Asset verification documents</h3><p>Laboratory, ownership, custody, insurance and reserve evidence when approved.</p></div></div></div></section>''')

pages['roadmap.html']=page('Roadmap',f'''<header class="hero"><div class="container"><div class="eyebrow">Program roadmap</div><h1>Build the infrastructure first.</h1><p>ReserveChain is in prelaunch. The platform is designed so business, legal and asset data can be added later without rebuilding core modules.</p>{disclosure}</div></header><section class="section alt"><div class="container"><div class="timeline"><div class="phase"><strong>Phase 01</strong><div><h3>Prototype & architecture</h3><p>Public site, registry model, passports, admin concept, security model and technical architecture.</p></div></div><div class="phase"><strong>Phase 02</strong><div><h3>Platform foundation</h3><p>Backend, database, CMS, authentication, audit trail and environments.</p></div></div><div class="phase"><strong>Phase 03</strong><div><h3>Blockchain & mobile</h3><p>Smart contracts, testnet, mobile apps and controlled integrations.</p></div></div><div class="phase"><strong>Phase 04</strong><div><h3>Verification & readiness</h3><p>Testing, security review, documentation, training and handover.</p></div></div></div></div></section>''')

pages['faq.html']=page('FAQ',f'''<header class="hero"><div class="container"><div class="eyebrow">Frequently asked questions</div><h1>Clear prelaunch boundaries.</h1>{disclosure}</div></header><section class="section alt"><div class="container grid g2"><div class="card"><h3>Are tokens currently for sale?</h3><p>No. No tokens are being offered or sold through this prototype.</p></div><div class="card"><h3>Is custody confirmed?</h3><p>No. Custody, insurance, reserve confirmations and related counterparties are not yet confirmed.</p></div><div class="card"><h3>Is ReserveChain MiCA-compliant?</h3><p>This prototype does not make that claim. The current plan does not intend to offer tokens to residents/persons located in the EU/EEA.</p></div><div class="card"><h3>Are asset values or token prices shown?</h3><p>No. The prototype intentionally avoids inventing valuations, token prices, ratios, rights or returns.</p></div></div></section>''')

pages['waitlist.html']=page('Waitlist',f'''<header class="hero"><div class="container"><div class="eyebrow">Registration of interest</div><h1>Join the prelaunch waitlist.</h1><p>Register interest in future ReserveChain updates. This does not reserve assets, prices, tokens or participation rights.</p>{disclosure}</div></header><section class="section alt"><div class="container grid g2"><div class="card"><form id="waitlistForm" class="form"><div class="field"><label>Name</label><input required name="name" placeholder="Your name"></div><div class="field"><label>Email</label><input required type="email" name="email" placeholder="name@example.com"></div><div class="field"><label>Interest</label><select name="type"><option>Project updates</option><option>Copper Powder program</option><option>Nickel Wire program</option><option>Enterprise / institutional</option></select></div><label class="small"><input required type="checkbox"> I understand this is only a registration of interest and not an investment, token purchase or asset reservation.</label><button class="btn primary" type="submit">Register interest</button><div id="formMsg" class="msg">Thank you. Your demo registration has been saved locally in this browser.</div></form></div><div class="card"><h3>Prototype behavior</h3><p>This contest demo stores waitlist submissions in the browser's local storage to demonstrate a functional flow without collecting real personal data on a production backend.</p><p>In production, submissions would be sent securely to the ReserveChain backend/CMS with consent records, anti-spam controls, audit logging and privacy handling.</p></div></div></section>''')

pages['admin.html']=page('CMS / Admin Demo',f'''<header class="hero"><div class="container"><div class="eyebrow">Proposed CMS structure</div><h1>Operate without code changes.</h1><p>The production CMS is designed to manage content, assets, documents, valuations, custody, insurance, reserve/token data, legal notices, SEO, languages, waitlist, enquiries, website modes and module visibility.</p></div></header><section class="section alt"><div class="container"><div class="admin-shell"><aside class="sidebar"><div class="brand" style="margin-bottom:22px"><span class="mark">R</span><span>Admin</span></div><a class="active">Dashboard</a><a>Asset Programs</a><a>Lots / Batches / Coils</a><a>Digital Passports</a><a>Documents</a><a>Custody & Insurance</a><a>Reserve Reports</a><a>Token Programs</a><a>Waitlist</a><a>Legal Notices</a><a>Languages</a><a>Audit Trail</a></aside><main class="adminmain"><div class="adminbar"><div><div class="eyebrow">Operations</div><h2 style="margin:0;font-size:28px">Dashboard</h2></div><span class="tag green">Development mode</span></div><div class="grid g3"><div class="card"><span class="small">Asset programs</span><div class="kpi">2</div><p>Illustrative programs configured</p></div><div class="card"><span class="small">Published passports</span><div class="kpi">0</div><p>No verified records published</p></div><div class="card"><span class="small">Modules inactive</span><div class="kpi">4</div><p>Wallet, purchase, PoR, redemption</p></div></div><div class="card" style="margin-top:20px"><h3>Content workflow</h3><div class="grid g3"><div><span class="tag">Draft</span><p class="small">Not public / not indexed</p></div><div><span class="tag warn">Under Review</span><p class="small">Awaiting approval</p></div><div><span class="tag green">Approved → Published</span><p class="small">Controlled release</p></div></div></div><div class="card" style="margin-top:20px"><h3>Append-only audit trail</h3><p>Production design requires tamper-evident administrative history that cannot be edited or removed through the normal admin interface.</p><div class="tablewrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Object</th><th>Result</th></tr></thead><tbody><tr><td>Demo</td><td>admin@example</td><td>Created</td><td>Copper Program Template</td><td>Draft</td></tr></tbody></table></div></div></main></div></div></section>''')

pages['architecture.html']=page('Technical Architecture',f'''<header class="hero"><div class="container"><div class="eyebrow">Proposed technical architecture</div><h1>One governed ecosystem.</h1><p>Website, CMS, APIs, asset registry, authentication, smart contracts and mobile applications share controlled backend services and auditable data flows.</p></div></header><section class="section alt"><div class="container"><div class="arch"><div class="node"><strong>Web App</strong><br>Public site + portal</div><div class="node"><strong>Mobile Apps</strong><br>iOS + Android</div><div class="node"><strong>API Gateway</strong><br>Auth, rate limiting, validation</div><div class="node"><strong>Core Backend</strong><br>CMS, registry, passports, workflows</div><div class="node"><strong>Data Layer</strong><br>Relational DB + secure object storage</div><div class="node"><strong>Identity</strong><br>MFA, RBAC, eligibility</div><div class="node"><strong>Audit Service</strong><br>Append-only events</div><div class="node"><strong>Blockchain</strong><br>ERC-20 + testnet tooling</div><div class="node"><strong>Monitoring</strong><br>Logs, alerts, backups</div><div class="node"><strong>Integrations</strong><br>KYC/KYB, email, future custody/PoR</div></div><div class="grid g3" style="margin-top:24px"><div class="card"><h3>Security</h3><p>RBAC, MFA, secure sessions, HTTPS, input validation, upload controls, rate limiting, environment isolation and secrets management.</p></div><div class="card"><h3>Environments</h3><p>Separate Development, Staging and Production with controlled deployment and rollback.</p></div><div class="card"><h3>Languages</h3><p>Content architecture prepared for English, Spanish and Italian.</p></div></div></div></section>''')

pages['schedule.html']=page('Development Schedule',f'''<header class="hero"><div class="container"><div class="eyebrow">Proposed delivery schedule</div><h1>Milestone-driven implementation.</h1><p>Indicative production plan. Final dates depend on approved scope, legal inputs, asset evidence, third-party accounts and owner acceptance.</p></div></header><section class="section alt"><div class="container"><div class="timeline"><div class="phase"><strong>Weeks 1–3</strong><div><h3>Discovery, UX, architecture</h3><p>Requirements lock, information architecture, data model, security plan and environments.</p></div></div><div class="phase"><strong>Weeks 4–8</strong><div><h3>Website, CMS, registry</h3><p>Public site, admin, asset programs, passports, documents, workflow states and audit trail.</p></div></div><div class="phase"><strong>Weeks 9–13</strong><div><h3>Backend, identity, APIs</h3><p>Authentication, MFA, RBAC, secure uploads, multilingual content and operational APIs.</p></div></div><div class="phase"><strong>Weeks 14–18</strong><div><h3>Smart contracts & testnet</h3><p>Configurable ERC-20 contracts, tests, deployment scripts, verification and admin procedures.</p></div></div><div class="phase"><strong>Weeks 19–24</strong><div><h3>iOS / Android</h3><p>Shared APIs, authentication, asset programs, passports, documents, holdings/transactions placeholders and notifications.</p></div></div><div class="phase"><strong>Weeks 25–28</strong><div><h3>Testing, hardening, handover</h3><p>Security review, accessibility, performance, backups/restore, store testing, manuals, training and transfer.</p></div></div></div><div class="notice">This schedule is an implementation proposal for planning purposes, not a promise of final launch dates. Production acceptance requires testing, documentation, independent verification and owner approval.</div></div></section>''')

for name,html in pages.items():
    (root/name).write_text(html,encoding='utf-8')
print('wrote',len(pages),'pages')
